import{t as e}from"./jsx-runtime-CY_jTiqj.js";import{A as t,C as n,E as r,M as i,N as a,O as o,P as s,S as c,T as l,_ as u,b as d,k as f,l as p,n as m,o as h,t as g,v as _}from"./shared-BLp3PbbW.js";import{t as v}from"./CodeEditor-DqHMt3P8.js";var y=e();function b({module:e}){return(0,y.jsxs)(a,{children:[(0,y.jsx)(i,{chip:e??`Глава 3 · Блок 10 · HTTP к готовому Planner`,title:`Чтение данных Planner`,intro:`Подключим к уже работающему FastAPI чтение того же Planner, которым пользуется CLI. Разберём, откуда обработчик берёт сервис и как он возвращает список и статистику, не создавая второе хранилище.`,variant:`project`}),(0,y.jsxs)(s,{number:`00`,title:`От проверки сервера к чтению Planner`,children:[(0,y.jsx)(o,{children:`Предыдущий шаг объяснял запуск приложения и запрос GET /health. Перед работой с данными повторим эту проверку в текущем проекте: прежнее описание само по себе не подтверждает состояние нашего checkout.`}),(0,y.jsx)(f,{variant:`connected`,items:[{title:`Точка старта`,description:`На входе ожидаются CLI, PlannerService, JsonStorage и FastAPI с маршрутом health; перед работой сверим их в проекте.`},{title:`Новый вопрос`,description:`Как HTTP-обработчик получит настроенный Planner и прочитает то же сохранённое состояние, что видит CLI?`},{title:`Результат`,description:`Мы подключим полный список задач и общую статистику, сохранив одну логику чтения и один источник данных.`}]}),(0,y.jsx)(`p`,{children:`CLI и сервер FastAPI работают как две отдельно запущенные программы, то есть два процесса со своей памятью. Сами объекты Python между ними не переходят. Общим остаётся сохранённый JSON, а правила чтения уже собраны в PlannerService. Мы проследим путь от HTTP-запроса до этого сервиса и научимся возвращать клиенту только нужные данные.`})]}),(0,y.jsxs)(s,{number:`01`,title:`Два процесса обращаются к одному файлу`,children:[(0,y.jsx)(o,{children:`Чтобы API и CLI показывали одни задачи, мы повторно используем готовую конфигурацию проекта, а не передаём объекты между процессами.`}),(0,y.jsx)(`p`,{children:`Процессом называют один запущенный экземпляр программы. У CLI свой набор объектов в памяти, у Uvicorn свой. Например, список Python, созданный внутри CLI, нельзя увидеть в памяти сервера. Совпадение имён переменных или импорт одного класса не объединяет эти два процесса.`}),(0,y.jsx)(`p`,{children:`Связь даёт файл. Фабрика build_service() собирает PlannerService с настроенным JsonStorage; хранилище знает путь к JSON. При вызове list_tasks() сервис запрашивает данные у хранилища, а успешная команда CLI сохраняет изменение туда же. Поэтому после завершения команды следующий HTTP-запрос может прочитать обновлённый файл, хотя Uvicorn продолжает работать.`}),(0,y.jsx)(t,{rows:[[`Память процесса`,`Хранит объекты только одного запущенного CLI или одного сервера.`],[`Настроенный JSON`,`Передаёт сохранённые данные между запусками, если CLI и сервер используют один путь.`]]}),(0,y.jsx)(`p`,{children:`Представим два рабочих кабинета и одну общую бумажную книгу в шкафу. Клиент в первом кабинете записывает изменение в книгу; человек во втором открывает её заново и видит последнюю запись. Кабинеты соответствуют процессам, а книга соответствует JSON-файлу. Это сравнение помогает понять постоянство данных, но не обещает безопасную одновременную запись: в нашей практике мы меняем данные последовательно.`}),(0,y.jsx)(`p`,{children:`В проекте CLI и API получают сервис через build_service(), фабрику, которая собирает объекты и передаёт сервису настроенное хранилище. Мы найдём реальный путь файла, не угадывая его по папке запуска. До изменений API снимем исходные значения: запустим CLI командой из README и после приглашения «Команда:» введём list и stats. Эти слова вводятся внутри CLI, не в PowerShell. Если задач нет, добавим одну через add для сравнения с API.`}),(0,y.jsx)(g,{caption:`Путь GET-запроса к сохранённым данным Planner`,orientation:`vertical`,children:(0,y.jsxs)(h,{label:`Последовательность чтения от запроса к JSON`,orientation:`vertical`,children:[(0,y.jsx)(p,{title:`HTTP-клиент`,shape:`terminator`,children:(0,y.jsx)(`p`,{children:`GET /tasks или GET /stats`})}),(0,y.jsx)(m,{label:`отправляет запрос`}),(0,y.jsx)(p,{title:`FastAPI-обработчик`,children:(0,y.jsx)(`p`,{children:`Получает текущий Request`})}),(0,y.jsx)(m,{label:`берёт сервис приложения`}),(0,y.jsx)(p,{title:`app.state.planner`,children:(0,y.jsx)(`p`,{children:`Хранит PlannerService`})}),(0,y.jsx)(m,{label:`вызывает чтение`}),(0,y.jsx)(p,{title:`PlannerService`,children:(0,y.jsx)(`p`,{children:`list_tasks() или get_statistics()`})}),(0,y.jsx)(m,{label:`запрашивает свежие данные`}),(0,y.jsx)(p,{title:`JsonStorage`,shape:`database`,children:(0,y.jsx)(`p`,{children:`Читает настроенный JSON-файл`})})]})}),(0,y.jsx)(`p`,{children:`Стрелки показывают путь запроса к данным. Ответ возвращается в обратном направлении: хранилище передаёт Task сервису, затем сервис передаёт результат обработчику, а FastAPI превращает возвращённый Python-список или словарь в JSON. Ответ использует формат передачи данных JSON; это не означает, что обработчик вручную читает или собирает файл.`})]}),(0,y.jsxs)(s,{number:`02`,title:`Request даёт доступ к сервису текущего приложения`,children:[(0,y.jsx)(o,{children:`FastAPI передаёт объект Request обработчику. Через него мы найдём сервис, сохранённый в app.state, и вызовем его внутри запроса.`}),(0,y.jsx)(`p`,{children:`Request представляет объект с данными текущего HTTP-запроса. Мы указываем его параметром обработчика и импортируем тип Request из fastapi; FastAPI передаёт объект при вызове функции. У него есть ссылка app на приложение. У приложения есть state, место для объектов, общих для его обработчиков. Путь request.app.state.planner означает: текущий запрос → его приложение → сохранённый там Planner.`}),(0,y.jsx)(`p`,{children:`При создании приложения один раз сохраняем в state результат build_service(). Там находится PlannerService с операциями Planner, а не список задач. Обработчик получает сервис и вызывает нужный метод; устройство хранения остаётся в прежнем слое. Проверим механику на независимом примере: сохраним подпись в приложении и вернём её маршрутом. FastAPI передаст Request нужного приложения, поэтому глобальную переменную app искать не нужно.`}),(0,y.jsx)(v,{caption:`Независимый пример: значение приложения через Request`,code:`from fastapi import FastAPI, Request

app = FastAPI()
app.state.banner = 'План работает'

@app.get('/about')
def about(request: Request):
    return {'banner': request.app.state.banner}`}),(0,y.jsx)(`p`,{children:`Здесь banner является строкой, которую мы сохранили в приложении. В Planner по тому же пути будет лежать сервис: request.app.state.planner. Получение ссылки на него ещё не читает задачи. Чтение произойдёт, когда обработчик вызовет метод сервиса.`}),(0,y.jsx)(d,{question:`Что находится в request.app.state.planner после настройки приложения?`,options:[`Список задач, загруженный один раз при импорте`,`Выбранный PlannerService, который умеет читать настроенное хранилище`,`Путь HTTP-маршрута /tasks`],correctIndex:1,explanation:`State хранит сервис приложения. Список задач сервис запрашивает у JsonStorage при вызове операции, поэтому изменение файла через CLI не требует пересоздавать список.`}),(0,y.jsx)(`p`,{children:`Мы передаём Request всем обработчикам, которым нужен Planner. Такой доступ связан с текущим приложением и сохраняет один понятный путь при дальнейшем переносе маршрутов в APIRouter. Пока маршруты остаются в app/api.py; отдельный роутер и тестовые подмены ещё не добавляем.`})]}),(0,y.jsxs)(s,{number:`03`,title:`Публичный ответ выбирает нужные поля`,children:[(0,y.jsx)(o,{children:`Доменная Task и HTTP-ответ решают разные задачи. Мы вернём из API только поля публичного договора, оставив полную запись без изменений.`}),(0,y.jsx)(`p`,{children:`Task является доменным объектом Planner, то есть внутренним представлением задачи, с которым работает программа. В нём есть id, title, priority, is_done и tags. Договор API открывает клиенту только первые четыре поля. tags остаётся в Task и в JSON; его отсутствие в HTTP-ответе не удаляет данные.`}),(0,y.jsx)(`p`,{children:`Проекция создаёт новый объект из выбранных полей исходной записи. Так мы задаём публичную форму ответа отдельно от внутренней модели. В независимом примере с карточкой книги оставим название и автора, а внутреннюю заметку не включим.`}),(0,y.jsx)(v,{caption:`Пример выборки полей для отдельной карточки`,code:`edition = {'title': 'Лесной маршрут', 'author': 'М. Лебедев', 'internal_note': 'проверить макет'}
card = {'title': edition['title'], 'author': edition['author']}
print(card)`}),(0,y.jsxs)(`p`,{children:[`edition['title'] берёт значение по ключу title, а пара 'title': ... помещает его в новый словарь card. print выведет `,(0,y.jsx)(`code`,{children:`{'title': 'Лесной маршрут', 'author': 'М. Лебедев'}`}),`. В card только два ключа; edition продолжает хранить внутреннюю заметку. В Planner такую проекцию собирает _task_read_data(task), чтобы оба маршрута возвращали одинаковую форму.`]}),(0,y.jsx)(`p`,{children:`Полная запись похожа на архивную папку, а проекция на окно выдачи, показывающее выбранные сведения. Окно не портит документы в папке. Так и Python-словарь ответа содержит выбранные атрибуты Task, но не заменяет объект и не становится новым хранилищем.`}),(0,y.jsx)(_,{code:`edition = {'title': 'Лесной маршрут', 'author': 'М. Лебедев', 'internal_note': 'черновик'}
card = {'title': edition['title'], 'author': edition['author']}
print(card)`,steps:[{line:1,note:`В card начинаем собирать отдельный словарь. edition остаётся полной исходной записью.`,vars:{edition:`{title, author, internal_note}`}},{line:1,note:`Берём значение title из edition и связываем его с ключом title новой карточки.`,vars:{"edition['title']":`'Лесной маршрут'`}},{line:1,note:`Точно так же добавляем автора. Ключ internal_note в card не появляется.`,vars:{card:`{'title': 'Лесной маршрут', 'author': 'М. Лебедев'}`}},{line:2,note:`print показывает выбранные поля. Исходный edition по-прежнему содержит внутреннюю заметку.`,vars:{result:`{'title': 'Лесной маршрут', 'author': 'М. Лебедев'}`}}]}),(0,y.jsx)(`p`,{children:`В примере мы читали значения словаря по ключам. В Planner значения объекта читаются через атрибуты: task.id, task.title и другие. Для коллекции применим helper к каждой Task. Проверим, почему не стоит возвращать клиенту внутренний объект целиком.`}),(0,y.jsx)(n,{code:`@app.get('/tasks')
def read_tasks(request: Request):
    tasks = request.app.state.planner.list_tasks()
    return [task.to_dict() for task in tasks]`,question:`Какое нарушение публичного договора может появиться в этом ответе?`,options:[`GET обязательно превращается в запись в JSON-файл`,`Полный to_dict может включить внутреннее поле tags`,`Пустая коллекция обязательно становится ответом 404`],correctIndex:1,explanation:`Доменное представление содержит больше полей, чем договор ответа. Для маршрута нужна явная проекция из четырёх значений, а исходная Task должна остаться полной.`})]}),(0,y.jsxs)(s,{number:`04`,title:`GET /tasks возвращает актуальную коллекцию`,children:[(0,y.jsx)(o,{children:`Теперь соединим знакомый list_tasks() с публичной проекцией. Каждый вызов маршрута получает полный список из текущего состояния Planner.`}),(0,y.jsx)(`p`,{children:`GET /tasks возвращает коллекцию, то есть весь набор задач. При запросе обработчик получает Planner через Request, вызывает list_tasks() и применяет _task_read_data к каждой Task. Пока это полный список: фильтры, сортировка и ограничение количества появятся позже и изменят правила выборки.`}),(0,y.jsx)(`p`,{children:`Обработчик возвращает Python-список словарей. FastAPI сам кодирует его в JSON; мы не используем print и не склеиваем строку JSON вручную. Пустой Planner даёт [] и успешный ответ: отсутствие элементов является нормальным состояние коллекции. 404 понадобится для отдельного запроса задачи по отсутствующему id.`}),(0,y.jsx)(`p`,{children:`Сравним два места чтения: запрос списка при каждом обращении и список, загруженный при импорте модуля, который останется старым после изменения через CLI. Нам нужен первый вариант.`}),(0,y.jsx)(l,{question:`Какой вариант покажет изменения JSON после завершённой команды CLI, пока Uvicorn остаётся запущенным?`,left:{title:`Читаем внутри запроса`,code:`def titles(request: Request):
    planner = request.app.state.planner
    return [task.title for task in planner.list_tasks()]`,note:`Сервис запрашивает текущее состояние в момент вызова маршрута.`},right:{title:`Сохраняем список при импорте`,code:`tasks = build_service().list_tasks()

def titles(request: Request):
    return [task.title for task in tasks]`,note:`Переменная tasks хранит снимок, созданный до следующего изменения файла.`},preferred:`left`,explanation:`Список должен загружаться через сервис внутри каждого обработчика. При первом варианте следующий GET увидит сохранённое CLI изменение, при втором ответ останется привязан к прежнему списку.`}),(0,y.jsx)(`p`,{children:`«Актуальный» означает, что новый вызов метода обращается к настроенному хранилищу во время запроса. Это не обещание безопасно объединять одновременные записи. В нашей проверке сначала завершается команда CLI, затем API читает сохранённое состояние.`})]}),(0,y.jsxs)(s,{number:`05`,title:`GET /stats использует готовый подсчёт`,children:[(0,y.jsx)(o,{children:`Общую статистику уже считает PlannerService. В API мы переименуем один ключ ответа и сохраним все значения сервиса.`}),(0,y.jsx)(`p`,{children:`Метод get_statistics() уже считает задачи и возвращает словарь с ключами all, open и done. Словарь хранит пары «ключ: значение». API переименует только all в total; open и done останутся без изменений. Обработчик не считает задачи заново и не выводит итог из списка HTTP-ответа.`}),(0,y.jsx)(`p`,{children:`Список отвечает на вопрос «какие задачи есть?», а статистика на вопрос «сколько задач в Planner?». Позднее список будет поддерживать выборку. Статистика всё равно описывает весь источник данных, а не только элементы, попавшие в конкретный ответ GET /tasks. На отдельном примере переименуем ключи готового отчёта и проследим, что числа останутся прежними.`}),(0,y.jsx)(u,{code:`service_counts = {'all': 5, 'current': 3, 'closed': 2}
report = {'total': service_counts['all'], 'active': service_counts['current'], 'archived': service_counts['closed']}
print(report)`,output:`{'total': 5, 'active': 3, 'archived': 2}`,hint:`Мы не пересчитываем исходные значения, только читаем их и записываем под другими ключами.`}),(0,y.jsx)(`p`,{children:`В примере числа остаются прежними, меняются только имена ключей. Так же маршрут переносит all в total, а open и done берёт из результата сервиса. Для пустого Planner все три значения равны нулю; это не ошибка 404.`}),(0,y.jsx)(c,{statement:`GET /stats должен считать только те задачи, которые уже вернул GET /tasks.`,isTrue:!1,explanation:`Статистика вызывает get_statistics() и охватывает весь источник. Она не зависит от списка ответа или его будущего ограничения.`}),(0,y.jsx)(c,{statement:`Если JsonStorage пуст, GET /tasks возвращает пустой список, а GET /stats возвращает нулевые значения.`,isTrue:!0,explanation:`Пустая коллекция является допустимым состоянием Planner. Отсутствующий отдельный id и пустой список имеют разный смысл.`})]}),(0,y.jsxs)(s,{number:`06`,title:`Чтение свежих данных не изменяет Planner`,children:[(0,y.jsx)(o,{children:`Проследим полный путь: CLI сохраняет изменение, работающий API читает его, а после перезапуска новый сервер снова находит те же данные.`}),(0,y.jsx)(`p`,{children:`GET-маршруты вызывают операции чтения. list_tasks() возвращает задачи, get_statistics() считает их; эти методы не сохраняют изменения. CLI-команда add создаёт открытую задачу с новым id. После неё total и open вырастут на один, done останется прежним. Запросы API сами не меняют файл.`}),(0,y.jsx)(`p`,{children:`Пустой файл и ошибка чтения представляют разные ситуации. Пустой Planner даёт [] и нулевые счётчики. Повреждённый JSON или отказ доступа вызывает StorageError; мы не маскируем её пустым результатом. Чтобы убедиться, что GET ничего не меняет, сначала завершим add, выйдем из CLI и зафиксируем JSON, затем отправим запросы и сравним файл. Иначе запись CLI можно ошибочно принять за побочный эффект API.`}),(0,y.jsx)(r,{tone:`info`,children:`Здесь мы не добавляем кэш задач, второй список в app.state или собственную работу с путём файла. В state лежит сервис; актуальные Task каждый раз запрашиваются через его существующий метод.`}),(0,y.jsx)(`p`,{children:`Ошибка чтения файла означает, что запрос не удалось выполнить. Проверим обработчик, который скрывает эту ошибку.`}),(0,y.jsx)(n,{code:`@app.get('/tasks')
def read_tasks(request: Request):
    try:
        tasks = request.app.state.planner.list_tasks()
    except StorageError:
        return []
    return [_task_read_data(task) for task in tasks]`,question:`Какой дефект появляется, если обработчик превращает StorageError в пустой список?`,options:[`Клиент не отличит пустой Planner от повреждённого файла или отказа доступа`,`FastAPI перестанет преобразовывать список Python в JSON`,`GET /stats начнёт считать только открытые задачи`],correctIndex:0,explanation:`Пустая коллекция является успешным ответом [], а StorageError сообщает о проблеме чтения. Если заменить ошибку пустым списком, клиент увидит ложное состояние Planner. Не перехватываем ошибку хранилища как отсутствие задач.`})]}),(0,y.jsxs)(s,{number:`07`,title:`Что мы будем делать в практике`,children:[(0,y.jsx)(o,{children:`В практике проверим каждое звено на фактическом проекте: от входных опор до двух ответов API.`}),(0,y.jsx)(f,{variant:`connected`,items:[{title:`Проверим точку входа и данные`,description:`Мы подтвердим состояние app/api.py, путь build_service() и фактический список CLI, затем сохраним baseline.`},{title:`Подключим список`,description:`Мы получим Planner через Request и app.state, применим общую проекцию, а GET /tasks сравним с полным CLI-list.`},{title:`Добавим статистику`,description:`Мы вызовем готовый get_statistics(), перенесём all в total и сверим все значения с CLI.`},{title:`Проверим свежесть`,description:`Мы изменим данные через CLI, повторим GET без перезапуска Uvicorn и подтвердим, что JSON не изменился от чтения.`}]}),(0,y.jsx)(`p`,{children:`В следующем занятии мы возьмём реальный id из списка и добавим маршрут одной задачи. Способ получить Planner через Request и общая проекция останутся теми же.`}),(0,y.jsx)(`p`,{children:`Сначала подтвердим вход: /health отвечает, Swagger или Planner API Local обращается к этому приложению, CLI запускается и показывает реальные данные. Если опора не готова, отметим точный сбой и не будем считать новые маршруты выполненными. Здесь добавляются только GET /tasks и GET /stats; фильтры, item-route, Pydantic и новые правила хранения относятся к следующим занятиям. Итог сверим с CLI до и после изменения данных.`})]})]})}export{b as Lesson48};